use "collections"

primitive Tokenizer
  fun vocab_size(): USize => 50257

  fun encode(text: String): Array[USize] val =>
    let tokens = recover iso Array[USize] end
    for char in text.values() do
      tokens.push(char.usize() % 50257)
    end
    consume tokens

  fun decode(token_ids: Array[USize] box): String =>
    let result = recover iso String end
    for token_id in token_ids.values() do
      result.push((token_id % 256).u8())
    end
    consume result

  fun byte_pair_encode(text: String): Array[USize] val =>
    encode(text)

  fun normalize(text: String): String =>
    text.lower()

  fun preprocess(text: String): String =>
    let normalized = normalize(text)
    let trimmed = normalized.clone()
    trimmed.>strip()
    trimmed
