use "collections"

class Optimizer
  let _learning_rate: F64
  let _beta1: F64
  let _beta2: F64
  let _epsilon: F64
  let _weight_decay: F64
  var _step: USize
  var _m: Map[String, Array[F64]] val
  var _v: Map[String, Array[F64]] val

  new create(
    learning_rate: F64 = 0.001,
    beta1: F64 = 0.9,
    beta2: F64 = 0.999,
    epsilon: F64 = 1e-8,
    weight_decay: F64 = 0.01
  ) =>
    _learning_rate = learning_rate
    _beta1 = beta1
    _beta2 = beta2
    _epsilon = epsilon
    _weight_decay = weight_decay
    _step = 0
    _m = recover val Map[String, Array[F64]] end
    _v = recover val Map[String, Array[F64]] end

  fun ref step(parameters: Map[String, Array[F64]] box, gradients: Map[String, Array[F64]] box): Map[String, Array[F64]] val =>
    _step = _step + 1

    let new_m = recover iso Map[String, Array[F64]] end
    let new_v = recover iso Map[String, Array[F64]] end
    let updated_params = recover iso Map[String, Array[F64]] end

    for (name, param) in parameters.pairs() do
      try
        let grad = gradients(name)?

        let m_prev = try _m(name)? else Array[F64].init(0.0, param.size()) end
        let v_prev = try _v(name)? else Array[F64].init(0.0, param.size()) end

        let m_new = Array[F64](param.size())
        let v_new = Array[F64](param.size())
        let p_new = Array[F64](param.size())

        for i in Range(0, param.size()) do
          let g = grad(i)?
          let m_val = (_beta1 * m_prev(i)?) + ((1.0 - _beta1) * g)
          let v_val = (_beta2 * v_prev(i)?) + ((1.0 - _beta2) * (g * g))

          m_new.push(m_val)
          v_new.push(v_val)

          let m_hat = m_val / (1.0 - _beta1.pow(_step.f64()))
          let v_hat = v_val / (1.0 - _beta2.pow(_step.f64()))

          let p_val = param(i)?
          let update = _learning_rate * (m_hat / (v_hat.sqrt() + _epsilon))
          let decay = _learning_rate * _weight_decay * p_val

          p_new.push(p_val - update - decay)
        end

        new_m(name) = m_new
        new_v(name) = v_new
        updated_params(name) = p_new
      end
    end

    _m = consume new_m
    _v = consume new_v
    consume updated_params

  fun get_learning_rate(): F64 => _learning_rate

  fun get_step(): USize => _step
